command:
timeout 110 bash -c 'node --input-type=module - <<'"'"'JS'"'"'
import {readFile} from '"'"'node:fs/promises'"'"';
import {createHash} from '"'"'node:crypto'"'"';
import {countProject} from '"'"'./scripts/count-loc.mjs'"'"';
const result=await countProject(process.cwd());
const files=[];
for(const entry of result.files) {
 const text=await readFile(entry.path,'"'"'utf8'"'"');
 const physicalLines=text.split('"'"'\n'"'"').length-(text.endsWith('"'"'\n'"'"')?1:0);
 if(physicalLines>999)throw new Error(entry.path+'"'"' exceeds 999 lines'"'"');
 files.push({...entry,physicalLines});
}
console.log(JSON.stringify({counter:result.counter,total:result.total,packages:result.packages,counterSha256:createHash('"'"'sha256'"'"').update(await readFile('"'"'scripts/count-loc.mjs'"'"')).digest('"'"'hex'"'"'),maxPhysical:Math.max(...files.map(x=>x.physicalLines)),largest:files.sort((a,b)=>b.prod-a.prod).slice(0,12),fileCount:files.length}));
JS
ps -eo pid,ppid,stat,comm
'

